WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (239::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Exámenes retadores']::TEXT[], '2026-10-23T00:00:00+00:00'::TIMESTAMPTZ, 'cc94c100574731e9b5bb6ac8a6bfbc0c37de994497f18cdb332390f196b52763'::TEXT, ARRAY[959]::BIGINT[]),
    (239::BIGINT, 'El mejor para máquinas aunque parece que para el próximo semestre (II 2025) no lo va a dar. Se entabla una buena amistad con él si participa bastante, los exámenes están hechos para que si usted sabe no se le complique tanto, pero si no tiene claro algunos aspectos teóricos no hay nada que hacer.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Exámenes retadores']::TEXT[], '2025-07-05T00:00:00+00:00'::TIMESTAMPTZ, '77a2159d297cf6b77e9a26e3c727818b9acba21f4977d761ff4decce651feb52'::TEXT, ARRAY[3053]::BIGINT[]),
    (239::BIGINT, 'Es muy buen profesor, lastima que no va a volver a dar el curso, pero ayuda mucho y explica increíble; hagan todos los quizzes y tares extra que deja y pasan. Vayan a consulta, a veces si le hacen ojos de perro y explica bien sus reclamos da pts.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2025-07-04T00:00:00+00:00'::TIMESTAMPTZ, 'aa09ccdaa8fcce90bd0e05b6209a9c004bca952ee7ead6cf40c9e961ed31f0f6'::TEXT, ARRAY[3053]::BIGINT[]),
    (239::BIGINT, 'El curso es difícil y los enunciados de los exámenes y tareas suelen ser poco claros, también explica un poco confuso, pero si le pregunta le ayuda a entender.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-29T00:00:00+00:00'::TIMESTAMPTZ, '4ce61df12e4cd198bea8ea5fd65a6d4b98ab34cb858cb8bf4a38bd18d2dfd6b7'::TEXT, ARRAY[3053]::BIGINT[]),
    (239::BIGINT, 'La materia en si es difícil, pero él intenta ayudar bastante, se pone en el lugar del estudiante y es abierto a dialogar fechas y evaluaciones. A veces puede ser un poco confusa su manera de explicar algunos temas, pero si se le pregunta. él hace todo lo posible por explicarlo mejor.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2025-06-26T00:00:00+00:00'::TIMESTAMPTZ, '75eef4857966e18773a804eff3a72f8502c967925bcbee70fec80c3a008b6d50'::TEXT, ARRAY[959]::BIGINT[]),
    (239::BIGINT, 'Muy ordenado, se vacila con el, es un curso pesado, lea del Chapman y practique del Fraile, lleve la materia al dia, los quices son faciles, los examenes son más conceptuales que matematicos, de cuidado , estudie con tiempo, pregunte y no falte a clases, la participacion si importa.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Clases excelentes']::TEXT[], '2024-12-09T00:00:00+00:00'::TIMESTAMPTZ, 'cc3c8074adf560818ceab1ad52c12df56e9c74c1567ef13cdecece634493d07e'::TEXT, ARRAY[959]::BIGINT[]),
    (239::BIGINT, 'La materia es muy pesada y a veces aburrida, además de que él a veces es un poco desordenado, pero él intenta que uno entienda. Usted solo asegúerese de entender bien y sino pedirle ayuda, ya solo con entender los ejercicios que hace en clase uno pasa.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Brinda apoyo']::TEXT[], '2024-11-27T00:00:00+00:00'::TIMESTAMPTZ, '433e88c2693067bbc33e3f16331e2246f5d0280145f0df061287c42863dedd7b'::TEXT, ARRAY[3053]::BIGINT[]),
    (239::BIGINT, 'El profe es realmente bueno, es muy buena gente y es bastante accesible. Para él es muy importante que usted ya llegue sabiendo antes de la clase por lo que se puede volver una carga, sin embargo es lo mejor que usted puede hacer. Califica duro pero siempre usted va a saber por qué lo hizo.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2024-11-05T00:00:00+00:00'::TIMESTAMPTZ, '590b5c8362a6ba5f0be3b524d2cb2b402fb9636866dfe07e41efc939dbe0bd69'::TEXT, ARRAY[3053]::BIGINT[]),
    (239::BIGINT, 'Buen profe, califica duro pero es la mejor opción para un curso tan pesado, ya que trata de dar la materia de la manera más concisa y clara posible para que el estudiante entienda. Las prácticas que propone son de gran ayuda.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2024-06-14T00:00:00+00:00'::TIMESTAMPTZ, '3828b38ae2e96e8054cc871c7267a74912b5ea69feb6f04fc8640f7d250951b3'::TEXT, ARRAY[3053]::BIGINT[]),
    (239::BIGINT, 'Es un curso sumamente denso y el profe hace lo mejor para que todos entiendan. Toca leerse los libros y las presentaciones para entender bien la materia y es casi obligatorio ir a clases. Es muy bueno en consulta y siempre responde. Tampoco es fácil pero es la mejor opción para este curso.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2024-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'ff680d93885066f8731601810a00e551f956e783dee10ade619c5c5af47f6e72'::TEXT, ARRAY[3053]::BIGINT[]),
    (239::BIGINT, 'El curso es pesado, si quiere pasar y entender bien casi que tiene que leerse 3 libros diferentes por semana. Hace quices semanales, si le cae bien el grupo se pasa de chistoso. Es importante que entienda bien los conceptos para salir bien en los quices. Vaya a consulta y haga ejercicios del Fraile.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2024-06-10T00:00:00+00:00'::TIMESTAMPTZ, '753ba9b37c022413274ea5f00d90990cd16737b52c545396b06fc1ee63bf81f4'::TEXT, ARRAY[959]::BIGINT[]),
    (239::BIGINT, 'Es muy buen profe. La materia es densa, toca leer el libro previamente y preguntar en clase. Vaya a consulta. Un curso pasable, pero depende de la actitud de uno.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2023-11-28T00:00:00+00:00'::TIMESTAMPTZ, '62d67c33804437ea24fbdd064515f6d6d2cf082f2cdda37aa90aa6b3f725596a'::TEXT, ARRAY[959]::BIGINT[]),
    (239::BIGINT, 'Para el lab el mae depende mucho de que usted vaya a teoría, si ya la llevó pues le toca volver a repasar las clases. 3 exámenes bastante accesibles, quices delos por perdidos y bitacoras semanales, nada fuera del otro mundo.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2023-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'ad2f4c11bfe09c0ff181797d958ab9c437f9cfe44376d9100ef607726a41e758'::TEXT, ARRAY[958]::BIGINT[]),
    (239::BIGINT, 'El profe es bastante bueno al menos para el lab de electri 1, se nota que le gusta lo que hace, pero a veces él piensa que uno ya es un experto en la vara y se enoja cuando uno hace la vara rápido.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2023-11-18T00:00:00+00:00'::TIMESTAMPTZ, '71038f90c9164b013c9dde63c7a5f457ca67b528b66738d0a9d721916640fcf5'::TEXT, ARRAY[925]::BIGINT[]),
    (239::BIGINT, 'Tengo sentimientos encontrados con él, explica muy bien y sabe demasiado, se preocupa porque uno aprenda y da muchas oportunidades. En las clases ni se resuelven ejercicios y aun así pone ejercicios muy difíciles en las pruebas, y evade algunas de sus responsabilidades recargando al alumno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2023-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'cd4c26e69b972cb7ba166098c220aaf69da5382bf41e5bcf3414bf75e3096294'::TEXT, ARRAY[959]::BIGINT[]),
    (239::BIGINT, 'El interés principal del profe es que aprenda. Las evaluaciones no son las más sencillas y es posible que lo majen, pero el profe da muchas oportunidades de recuperarse, más que todo a final de semestre. El profe usa la clase para repasar lo más complicado de la materia que tiene que llevar leída.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Da crédito extra']::TEXT[], '2023-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'e1b94de575c36a644e19e0acee15bf4c60245e697a506c021ac0efe89964f1fc'::TEXT, ARRAY[959]::BIGINT[]),
    (239::BIGINT, 'El profe es bastante argollero, no sea un lamewebos ni un desinteresado. Trate de poner atención y preguntar, gáneselo con su esfuerzo. Es un curso que solo él da, las clases son solo teoría, compleja y va demasiado rápido. Los exámenes son mitad práctico, toca estudiar por uno mismo'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Exámenes retadores']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '4ec7c2b52ae09e7dbe9ad150e56392410a5572af9501108d15b249eb7c2af175'::TEXT, ARRAY[959]::BIGINT[]),
    (239::BIGINT, 'El profe es buena nota. A veces se enreda pero maneja bien la materia. Los exámenes tienen un nivel similar al visto en clase aunque sí los complica un poco. La primera parte del curso la da muy rápido ya que él lo prepara para maquinas, no para electri 3.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Clases largas']::TEXT[], '2023-02-02T00:00:00+00:00'::TIMESTAMPTZ, '78b317f10acfb3a29af7009cbe7d61ec1ee09a1cb65ab9ae142f0bfcfc66b22c'::TEXT, ARRAY[942]::BIGINT[]),
    (239::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-10T00:00:00+00:00'::TIMESTAMPTZ, '1b6efecc871845d5f852ee11b6e79dbda4e3cedd8db96cc4fe04119196abe8e5'::TEXT, ARRAY[959]::BIGINT[]),
    (239::BIGINT, 'El profe da la materia de manera muy desordenada, solo ve teoría y en los exámenes son de puros ejercicios por ende hay que ser muy autodidacta con los ejercicios. Las presentaciones son muy desordenadas, no da tiempo para verlas todas y el profesor habla de temas que no tienen nada que ver.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Pocos exámenes']::TEXT[], '2022-06-30T00:00:00+00:00'::TIMESTAMPTZ, '359f4d9c3340d33d6a1fb8b7408764e5fd91108408e5da89bf49c10e88e69822'::TEXT, ARRAY[959]::BIGINT[]),
    (239::BIGINT, 'LA PERSONA MÁS DESORDENADA QUE HE CONOCIDO EN MI VIDA, ES INCREÍBLE'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-11T00:00:00+00:00'::TIMESTAMPTZ, '762baf41f4d7a05b288fb0832be9b6c8363fc9ced04301a24299b8ddcb7eaf92'::TEXT, ARRAY[959]::BIGINT[]),
    (239::BIGINT, 'Fatal'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Da crédito extra']::TEXT[], '2022-03-29T00:00:00+00:00'::TIMESTAMPTZ, '466c53437f2991452c5c2bb3aad6f939a68c77cd3570a8f891391b6ea1b1101b'::TEXT, ARRAY[959]::BIGINT[]),
    (239::BIGINT, 'Es un hijueputa, Osvaldo maldito (Por si está leyendo esto) No da problemas, es desordenado, pedante...'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-02-23T00:00:00+00:00'::TIMESTAMPTZ, 'cc90550e8aa3d7fa4578c8de7de79225aa0f845e175d4251683085e76bfe3239'::TEXT, ARRAY[959, 3053]::BIGINT[]),
    (239::BIGINT, 'El peor profesor con el que me he topado, no solo en la escuela de electromecánica, si no en todos los cursos que he llevado. Discutir con el es tan útil como hablarle a una piedra.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2021-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'b50f9580a9fbd3c04f2235a0d6a5f09f7534450b80fe1f23bf4ac1b9545cff53'::TEXT, ARRAY[959, 941]::BIGINT[]),
    (239::BIGINT, 'Es pésimo profesor, no sabe aceptar cuando se equivoca, contradice el libro, en clases dice una cosa en el examen otra. Es cizañoso y toma las cosas personales. No ayuda a nada, ni explica bien'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2021-11-11T00:00:00+00:00'::TIMESTAMPTZ, 'f52d8f62dab2bf6b09d79b1cf1270091f4d7f6b3e01831f365ce57897c1dea08'::TEXT, ARRAY[959, 3053]::BIGINT[]),
    (239::BIGINT, 'Profesor pedante, mal intencionado. Le encanta perjudicar a los estudiantes para luego decir que la evaluación estaba fácil. Literalmente no hace ni un solo problema en clase y dice que el tutor se encarga de eso. Se está robando el salario este individuo. No se recomienda pero es la única opción.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2021-10-31T00:00:00+00:00'::TIMESTAMPTZ, '8624c86feb5b47bd0214dc0db038283ad63f4add1c2bc73666690f91aa5577e2'::TEXT, ARRAY[959]::BIGINT[]),
    (239::BIGINT, 'Tiene que estudiar mucho por su cuenta y poner atención en clase si no estás frito. El profe es muy cerrado, a veces se contradice con el libro. No regala puntos a final de semestre, aunque es posible que el dé ayudas grupales a mitad de semestre. Es un curso muy demandante, tengalo presente siempre'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, '22cd58e1c15ff0d915d96b7bb4ef67077581f6c25cf326fb2a912b3999b8480a'::TEXT, ARRAY[959]::BIGINT[]),
    (239::BIGINT, 'Mal profesor y peor persona. No explica problemas y hace evaluaciones que no van con lo enseñado en clase. En clases habla pura paja de su “experiencia” laboral en hoteles, por ende, no tiene nada que ver con la materia del curso. Mal intencionado a la hora de evaluar, pedante, prepotente, argollero'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2021-02-24T00:00:00+00:00'::TIMESTAMPTZ, '05a415a78d1d5ad235155ed65d691cb619e886f987ed8a2c09f9ecf32a2c97d6'::TEXT, ARRAY[959]::BIGINT[]),
    (239::BIGINT, 'Manda a leer 3 libros pero al final solo vale lo que él diga a partir de su experiencia. Baja puntos por cada minuto que uses en los quices. Mete como quiz enunciados de parcial pasados pero da 1/4 de tiempo (apróx 8 a 10 min). Enunciados ambiguos tipo examen de admisión. No hay otra opción :('::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2021-02-11T00:00:00+00:00'::TIMESTAMPTZ, '5ee4698d9509830cc38945f16a6ffeb61d252c7ec2110dc59bf0fef5706154cf'::TEXT, ARRAY[959]::BIGINT[]),
    (239::BIGINT, 'Super recomendado, explica super bien y ayuda un montón si no entiendes algo. Las evaluaciones son claras, realmente se aprende con él y de hecho creo que aprendi muchísimo mas con él que en el curso de teoría.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'd0eef5080aa4574adbc9bc2924b9ec68d1e9d2521c86b5f5f7a2aedf7f2f0df7'::TEXT, ARRAY[3054]::BIGINT[]),
    (239::BIGINT, 'No hay opción, hay cursos que se deben llevar con él. No siempre se estará de acuerdo con él y sus "tratos" o las instrucciones en quices y exámenes, pero es lo que hay. Si le discuten, pierden. No vaya con miedo, y vaya a consulta, participe, que se aprenda su nombre por esforzado'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Exámenes retadores']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, '39293bb150969510e658f7a1c17f6c4d77d5ee2991b25958bc0c28ce758b1eca'::TEXT, ARRAY[958, 3054]::BIGINT[]),
    (239::BIGINT, 'Yo matricule con este profesor el II Semestre del 2020, los quices son ambiguos y da muy poco tiempo para hacer los exámenes como puede ser que te 1h a solo 20min para hacer selección única y la parte de desarrollo califica binario un error y tenés cero y suele ser peor si le reclama.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-01-16T00:00:00+00:00'::TIMESTAMPTZ, '01e4233898c3ae98ddba657c2febbdb46599258c1663876a5e8c6dc218777a47'::TEXT, ARRAY[959]::BIGINT[]),
    (239::BIGINT, 'En clases VIRTUALES: Explica muy bien, eso no se lo quita nadie, pero los enunciados de quices y exámenes son muy ambiguos y da muy poco tiempo para las evaluaciones.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2020-12-18T00:00:00+00:00'::TIMESTAMPTZ, 'ed2c591c7af9a77bf63647db5be71618b05e5e8b44b07a3cbaa106c37087bee3'::TEXT, ARRAY[959]::BIGINT[]),
    (239::BIGINT, 'El profe explica aceptable, pero exige que se lean 3 libros y eso demanda demasiado tiempo, piensa que sólo ese curso existe. Hay que estudiar demasiado y es pasable si es responsable, en algunas evaluaciones pretende que se interpreten aspectos que no son claros en la redacción. El Lab es fácil'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Exámenes retadores']::TEXT[], '2020-12-16T00:00:00+00:00'::TIMESTAMPTZ, 'b364f1686d2e5bac8c4da0ebbe1d4c2e184be3e1b62892aafa7e1e7647d4b4b9'::TEXT, ARRAY[958, 3054]::BIGINT[]),
    (239::BIGINT, 'Estoy llevando el curso de máquinas eléctricas el II del 2020, estoy decepcionado de ese curso y ese profesor. No explica problemas, es prepotente, arrogante, se cree la última maravilla y habla mal de otros profesores en sus clases. Creo es poco profesional y muy antiético. El oepeor profe'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2020-12-14T00:00:00+00:00'::TIMESTAMPTZ, '2017b82c8cfc3446c49a11af61d67076053b3866157679f5f02f6f51bc9ca94f'::TEXT, ARRAY[959]::BIGINT[]),
    (239::BIGINT, 'No recomiendo llevar este curso con este profesor si Sebastian Mata lo esta dando, lleven con Sebas. Si les gusta un profesor que los trate mal matriculen sin miedo con Osvaldo'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2020-12-01T00:00:00+00:00'::TIMESTAMPTZ, '0e9de8b9a724f883ac228f2d137ee51b2a21ff8119aeada21f142ca981bce525'::TEXT, ARRAY[941]::BIGINT[]),
    (239::BIGINT, 'Virtual, el lab es excelente uno aprende igual o más que en presencial por la plataforma que usa, en teoría es muy bueno y sabe mucho, eso sí la materia es pesada y hay que leer bastante, pero el profe ayuda a que el curso sea más llevadero.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-09T00:00:00+00:00'::TIMESTAMPTZ, 'ac9f443f0e43e6c4e1488d348834e9fdef88744574fda2ca0ac39c5fe9ab351c'::TEXT, ARRAY[958, 3054]::BIGINT[]),
    (239::BIGINT, 'Completamente recomendado para llevar este lab, tanto de forma presencial como virtual. Ayuda bastante, explica cada tema muy claramente, e incentiva el interés del estudiante hacia la materia. Puede ser medio argollero eso sí.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2020-08-04T00:00:00+00:00'::TIMESTAMPTZ, 'dffb4a51e88fd0994555a9ebfdaf2b0201313892814c4e2e5c5d155cb020064d'::TEXT, ARRAY[3054]::BIGINT[]),
    (239::BIGINT, 'Con la moldalidad virtual el profe nos ayudó mejor. Algunas evaluaciones fueron en grupo, se preocupa que estemos aprendiendo y cómodos con el grupo. Graba las clases y ayuda mucho porque a veces va muy rápido en la clase. Matriculen a la mayoría nos fue bien'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-30T00:00:00+00:00'::TIMESTAMPTZ, 'bb14f8ae06cb48caceb0f53011622bdc3f43a7ac80eff90907b8e712983c4b20'::TEXT, ARRAY[959]::BIGINT[]),
    (239::BIGINT, 'De todos mis profes, este fue el que mejor se adaptó a la virtualidad. Siempre nos preguntaba si estábamos de acuerdo con las propuestas para continuar el curso, siempre dispuesto a ayudarnos para que pudiésemos aprender. En fin, 10/10, si puede matricular con él no lo dude.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-15T00:00:00+00:00'::TIMESTAMPTZ, '8fc542de1fe068037f585a4131956d36d2229d5514080322c66a62cf9efed112'::TEXT, ARRAY[958]::BIGINT[]),
    (239::BIGINT, 'Mal profesor, mal intencionado, busca como perjudicar al estudiante en las evaluaciones. Evaluaciones con niveles de dificultad demasiado elevada. En todo el semestre vimos solo 1 ejemplo completo y dejaba la reolución de ejemplos. No ayuda nada en consulta, dice que es deber de uno como estudiante.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-06-20T00:00:00+00:00'::TIMESTAMPTZ, '6973f8df7550f2557679498273fb1c5731ff78526e016c91493f42aaa75bf520'::TEXT, ARRAY[959]::BIGINT[]),
    (239::BIGINT, 'El mae hace que el curso valga unos 2 créditos por lo menos, además el sistema que maneja que no hay guia de lab sino que el estudiante tiene que intuirla es un poco rudo, al final lo que busca es que uno vaya a consulta para que ahí puedar explicarle, lo recomiendo por es el menos malo'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'bb6d1a5f910a1e9ed3fef74622bcfcd920f440f065e6b5dc59a8628661d92edc'::TEXT, ARRAY[958]::BIGINT[]),
    (239::BIGINT, 'Hace que uno le ponga bastante por lo que uno termina aprendiendo un montón. Le cuesta aceptar sus errores, entonces reclamarle es bastante tedioso.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2019-12-01T00:00:00+00:00'::TIMESTAMPTZ, '52737775205305f16dc0df1bb0ca37d65f50fb9044012da5d94435e7bd267e23'::TEXT, ARRAY[959]::BIGINT[]),
    (239::BIGINT, 'La forma en que trata depende mucho se cómo ve que se comporta el grupo. Domina muy bien la materia y a veces da tips para los examenes. Es un poco argollero, pero uno puede ganarse su respeto.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'b5162248235e3349491fb94f142cb952ae733832e0a321ddf2360ec3b71d8d5f'::TEXT, ARRAY[959]::BIGINT[]),
    (239::BIGINT, 'Muy buena gente pero califica duro y mete ejercicios con muchos conceptos, sopla como va hacer el quiz y el examen si siempre va a consulta'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2019-10-21T00:00:00+00:00'::TIMESTAMPTZ, 'fa9f28e56689a9eb4b5da02af0013a008f1d3a6842401c970999eca20f8984be'::TEXT, ARRAY[942]::BIGINT[]),
    (239::BIGINT, 'Que no lo vea llegando tarde, es preferible que se salga antes de la clase, antes que llegar tarde. En realidad el curso se pasa haciendo ejercicios de tutoría y los libros recomendados, no espere que lo explicado en clase sea suficiente para el examen.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Exámenes retadores']::TEXT[], '2019-06-22T00:00:00+00:00'::TIMESTAMPTZ, '840bae39d9668068d9739ac82aef7b77e2c03c9f604a4c366062a6652b03f16c'::TEXT, ARRAY[942]::BIGINT[]),
    (239::BIGINT, 'Te enseña muchas cosas extra muy útiles. Es muy estricto con la puntualidad. Es flexible con las evaluaciones. Es amigable y uno aprende mucho'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, '0f34f840135d12130d9f461e6c97e63e96516f2eb31902ec314850a2dc87c2ed'::TEXT, ARRAY[3054]::BIGINT[]),
    (239::BIGINT, 'Explica muy bien. Es muy exigente con la puntualidad de las clases, pero brinda mucha ayuda en el curso para que los temas queden claros'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-14T00:00:00+00:00'::TIMESTAMPTZ, '0763901d47fecc63df95e0b02413d906351d95b5930476eb2c8dfe991603d8f8'::TEXT, ARRAY[3054]::BIGINT[]),
    (239::BIGINT, 'Explica la presentación que trae que son recortes de diferentes libros en donde resume los contenidos de estos, la materia la da ordenada y hace uno que otro ejemplo en clase, sus exámenes son difíciles. Hay que ponerle, practicar mucho y leer los libros de donde saca la materia.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Exámenes retadores']::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, '8d3c433b09b27eddc04261b0580bff2d2d665b0e79419d68523fc3000ae03406'::TEXT, ARRAY[942]::BIGINT[]),
    (239::BIGINT, 'Las clases eran pantallazos de los libros y sus solucionarios. Pocas veces se puso a resolver un problema en la pizarra. Los exámenes son durísimos y se parecen poco a lo que se ve en la clase, además, el enunciado no es claro. El profe sabe mucho, pero parecía que no tenía ganas de dar la clase.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2019-06-09T00:00:00+00:00'::TIMESTAMPTZ, '7ecc35b472adc4c9f3062c6beee435c444ea313c43fc4dcbe657721b3915bef5'::TEXT, ARRAY[942]::BIGINT[]),
    (239::BIGINT, 'Un Dios. Explica super bien y ayuda mucho en los laboratorios, a veces incluso demasiado. Se interesa bastante en que uno aprenda lo más posible.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-05-31T00:00:00+00:00'::TIMESTAMPTZ, '0d5d5c4981ea1f2fb59b4e7669d837bde1f6775e192fe9de8002e27628d3d19f'::TEXT, ARRAY[3054]::BIGINT[]),
    (239::BIGINT, 'Sus clases son puras presentaciones, de las cuales el 100% son recortes de libros y no explica bien los temas. No domina los temas al nivel de poder explicarlos. Si usted le pone otro método como solución le dice que así no es. También dice "Yo soy el profesor, yo soy el que sabe, ustedes no."'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2019-05-19T00:00:00+00:00'::TIMESTAMPTZ, '0ead642150fad8944d77e511d71374c891ae2d3471a3d69af42033893354d090'::TEXT, ARRAY[942]::BIGINT[]),
    (239::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-21T00:00:00+00:00'::TIMESTAMPTZ, '6b09888362ab26aae53eb365d352736067a5922fde6eafb5cf3786773da4d3bd'::TEXT, ARRAY[959]::BIGINT[]),
    (239::BIGINT, '"Diayyyyyyyyyyyyyyyyyyyy Papillo!!!!, Excelente profesor, eso si vaya mucho a consulta el aprecia el esfuerzo del estudiante y pregunte sin miedo, que una vacilada todos nos la llevamos!!! explica Claro y muy entendible!!! el problema es que los quices no los califica él.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-29T00:00:00+00:00'::TIMESTAMPTZ, '1edff0623d026b2309c636cf15942ea7e8b5424eedd548db90bbe7ee7c7fdd88'::TEXT, ARRAY[959]::BIGINT[]),
    (239::BIGINT, 'El profesor es muy tuanis como persona, la teoría la explica súper bien, el problema es que solo explica teoría, ni un solo problema en clases, y los exámenes son 50 teoría y 50 problemas. Para los examenes y quices tiene que ser un poco autodidacta. Pero le va a gustar mucho el curso'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-11-24T00:00:00+00:00'::TIMESTAMPTZ, '42682c314e2fc886645bc735f9b26ad91e2f003f6786ec9b176312ec892f49cb'::TEXT, ARRAY[959]::BIGINT[]),
    (239::BIGINT, 'Le importa que uno aprenda y se vuelva autodidacta. Tiene un sistema muy diferente a los demás profes pero es solo de agarrarle el toque. Las evaluaciones son duras pero al calificarlas es muy detallado (cosas que no parecieran importantes el las evalúa y con eso le ayuda en la nota).'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-29T00:00:00+00:00'::TIMESTAMPTZ, '7a5a2c85dc13d3f985eeb569c607a4de9e2dbf31c6e1a0886e46fd3e2f18ed51'::TEXT, ARRAY[959]::BIGINT[]),
    (239::BIGINT, 'El mejor profesor de electromecánica que he tenido! Explica muy bien, de verdad le interesa que uno aprenda.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'cd2babf50f82f919661b50b62169faafe6703e4e5a0d94e65f188054a6bbb1b1'::TEXT, ARRAY[959]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
